	bool _has_accel;
	int _split_type = JS_SPLIT_TYPE_FULL;
	int _ctrlr_type = JS_TYPE_UNKNOWN;
	int _vendorId = JS_VENDOR_UNKNOWN;
	int _productId = JS_PRODUCT_UNKNOWN;
