bool do_RESET_MAPPINGS(CmdRegistry *registry)
{
	COUT << "Resetting all mappings to defaults\n";
	static constexpr auto callReset = [](JSMButton &map)
	{
		map.reset();
	};
	ranges::for_each(mappings, callReset);
