	input.ki.dwFlags = pressed ? 0 : KEYEVENTF_KEYUP;
	if (isExtendedKey(vkKey))
	{
		input.ki.dwFlags |= KEYEVENTF_EXTENDEDKEY;
	}

	if (isNumLockKey(vkKey))
	{
		input.ki.wVk = vkKey.code;
		input.ki.wScan = 0;
	}
	else
	{
		input.ki.wVk = 0;
		input.ki.wScan = MapVirtualKey(vkKey.code, MAPVK_VK_TO_VSC);
		input.ki.dwFlags |= KEYEVENTF_SCANCODE;
	}

	return SendInput(1, &input, sizeof(input));
}

void moveMouse(float x, float y)
{
	accumulatedX += x;
	accumulatedY += y;

	int applicableX = (int)accumulatedX;
	int applicableY = (int)accumulatedY;

	accumulatedX -= applicableX;
	accumulatedY -= applicableY;
	//COUT << setprecision(4) << accumulatedX << ' ' << accumulatedY << '\n';

	INPUT input;
	input.type = INPUT_MOUSE;
	input.mi.mouseData = 0;
	input.mi.time = 0;
	input.mi.dx = applicableX;
	input.mi.dy = applicableY;
	input.mi.dwFlags = MOUSEEVENTF_MOVE;
	SendInput(1, &input, sizeof(input));
}

void setMouseNorm(float x, float y)
{
	INPUT input;
	input.type = INPUT_MOUSE;
	input.mi.mouseData = 0;
	input.mi.time = 0;
	input.mi.dx = LONG(roundf(65535.0f * x));
	input.mi.dy = LONG(roundf(65535.0f * y));
	input.mi.dwFlags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE;
	SendInput(1, &input, sizeof(input));
}

BOOL WriteToConsole(string_view command)
{
	static const INPUT_RECORD ESC_DOWN = { KEY_EVENT, { TRUE, 1, VK_ESCAPE, WORD(MapVirtualKey(VK_ESCAPE, MAPVK_VK_TO_VSC)), VK_ESCAPE, 0 } };
	static const INPUT_RECORD ESC_UP = { KEY_EVENT, { FALSE, 1, VK_ESCAPE, WORD(MapVirtualKey(VK_ESCAPE, MAPVK_VK_TO_VSC)), VK_ESCAPE, 0 } };
	static const INPUT_RECORD RET_DOWN = { KEY_EVENT, { TRUE, 1, VK_RETURN, WORD(MapVirtualKey(VK_RETURN, MAPVK_VK_TO_VSC)), VK_RETURN, 0 } };
	static const INPUT_RECORD RET_UP = { KEY_EVENT, { FALSE, 1, VK_RETURN, WORD(MapVirtualKey(VK_RETURN, MAPVK_VK_TO_VSC)), VK_RETURN, 0 } };

	vector<INPUT_RECORD> inputs(0);
	inputs.reserve(command.size() + 4);
	inputs.push_back(ESC_DOWN);
	inputs.push_back(ESC_UP);

	for (auto c : command)
	{
		INPUT_RECORD ir;
		ir.EventType = KEY_EVENT;
		ir.Event.KeyEvent.bKeyDown = TRUE;
		ir.Event.KeyEvent.wRepeatCount = 1;
		string name(1, toupper(c));
		auto vkc = nameToKey(name);
		ir.Event.KeyEvent.wVirtualKeyCode = vkc;
		ir.Event.KeyEvent.wVirtualScanCode = MapVirtualKey(vkc, MAPVK_VK_TO_VSC);
		ir.Event.KeyEvent.uChar.UnicodeChar = c;
		ir.Event.KeyEvent.dwControlKeyState = 0;

		inputs.push_back(ir);
	}
	inputs.push_back(RET_DOWN);
	inputs.push_back(RET_UP);

	DWORD written;
	if (WriteConsoleInput(GetStdHandle(STD_INPUT_HANDLE), inputs.data(), inputs.size(), &written) == FALSE)
	{
		auto err = GetLastError();
		CERR << "Error writing to console input: " << err << '\n';
	}
	FlushConsoleInputBuffer(GetStdHandle(STD_INPUT_HANDLE));
	return written == inputs.size();
}

BOOL WINAPI ConsoleCtrlHandler(DWORD dwCtrlType)
{
	// https://docs.microsoft.com/en-us/windows/console/handlerroutine
	switch (dwCtrlType)
	{
	case CTRL_C_EVENT:
	case CTRL_BREAK_EVENT:
	case CTRL_CLOSE_EVENT:
		WriteToConsole("QUIT");
		return TRUE;
	}
	return FALSE;
};

// just setting up the console with standard stuff
void initConsole()
{
	AllocConsole();
	SetConsoleTitle(L"JoyShockMapper");
	// https://stackoverflow.com/a/15547699/1130520
	freopen_s((FILE **)stdin, "conin$", "r", stdin);
	freopen_s((FILE **)stdout, "conout$", "w", stdout);
	freopen_s((FILE **)stderr, "conout$", "w", stderr);
	SetConsoleCtrlHandler(&ConsoleCtrlHandler, TRUE);
}

tuple<string, string> GetActiveWindowName()
{
	HWND activeWindow = GetForegroundWindow();
	if (activeWindow)
	{
		string module(256, '\0');
		string title(256, '\0');
		GetWindowTextA(activeWindow, &title[0], title.size()); //note: C++11 only
		title.resize(strlen(title.c_str()));
		DWORD pid;
		// https://stackoverflow.com/questions/14745320/get-active-processname-in-vc
		if (GetWindowThreadProcessId(activeWindow, &pid))
		{
			HANDLE hProcess = OpenProcess(PROCESS_QUERY_INFORMATION, FALSE, pid);
			if (hProcess)
			{
				DWORD len = DWORD(module.size());
				if (QueryFullProcessImageNameA(hProcess, 0, &module[0], &len))
				{
					auto pos = module.find_last_of("\\");
					module = module.substr(pos + 1, module.size() - pos);
					module.resize(strlen(module.c_str()));
					if (title.empty())
					{
						title = module;
					}
				}
				CloseHandle(hProcess);
				return { module, title };
			}
		}
	}
	return { "", "" };
}

vector<string> ListDirectory(string directory)
{
	vector<string> fileListing;

	// Prepare string for use with FindFile functions.  First, copy the
	// string to a buffer, then append '\*' to the directory name.

	if (directory[directory.size() - 1] != '\\')
		directory.append("\\");
	directory.append("*");

	// Find the first file in the directory.

	WIN32_FIND_DATAA ffd;
	auto hFind = FindFirstFileA(directory.c_str(), &ffd);

	if (hFind == INVALID_HANDLE_VALUE)
	{
		return {};
	}

	// List all the files in the directory with some info about them.

	do
	{
		// Ignore directories
		if ((ffd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) == 0)

		{
			fileListing.push_back(ffd.cFileName);
			//COUT << "File: " << ffd.cFileName << '\n';
		}
	} while (FindNextFileA(hFind, &ffd) != 0);

	auto dwError = GetLastError();
	if (dwError != ERROR_NO_MORE_FILES)
	{
		CERR << "Error code " << dwError << " raised with FindNextFile()\n";
	}

