			bool isLeft = stickMode == StickMode::LEFT_ANGLE_TO_X || stickMode == StickMode::LEFT_ANGLE_TO_Y;

			float stickAngle = isX ? atan2f(stickX, absY) : atan2f(stickY, absX);
